import{z as o,x as i,o as B,c as p,q as s,j as t,D as A,d as e,s as l,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"基准设计的陷阱","description":"","frontmatter":{"title":"基准设计的陷阱","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pe3-benchmark-pitfalls.md","filePath":"cs/pe3-benchmark-pitfalls.md","lastUpdated":1791063341000}'),d={name:"cs/pe3-benchmark-pitfalls.md"};function D(m,E,C,c,h,F){const r=i("Mermaid");return B(),p("div",null,[E[2]||(E[2]=s('<h1 id="基准设计的陷阱" tabindex="-1">基准设计的陷阱 <a class="header-anchor" href="#基准设计的陷阱" aria-label="Permalink to &quot;基准设计的陷阱&quot;">​</a></h1><div class="epigraph"><p>选错负载，比用错仪器更彻底地毁掉一次测量；仪器错了你知道数不可信，负载错了你还信。</p><footer>—— 据 Jain，The Art of Computer Systems Performance Analysis，1991，第一章的负载选择口径整理</footer></div><p><a href="/cs/pe3-requirements">上一课</a>把性能承诺变成数字与验收协议，但协议只说「怎样算过」，没说数字从哪来。本课补这一环：基准。基准的困境是双重的——它既要代表目标负载，又必须可复现，而这两个要求天然互相拉扯：越真实越不可控，越可控越失真。本课把这条张力上最常见的陷阱列成清单，并给每条配一个控制手段。主干课的<a href="/cs/spec-benchmark-pitfalls">SPEC 与基准陷阱</a>与<a href="/cs/tpc-benchmarks">TPC-C / TPC-H</a>讲过标准化基准的纪律，本课讲自己搭基准时的同款错误。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次基准有四个环节可以出错：负载生成、被测系统的状态、平台环境、统计判读。任何一环失守，数字都还「看起来很准」——有单位、有小数点、能画成曲线，唯独不再回答上一课定下的那个问题。不这么做会错在哪：负载用均匀固定大小的请求，而真实流量是突发长尾的，基准于是选中了系统最舒服的工作模式；数据库冷着缓存测第一遍，把页缓存预热当成了系统性能；两台机器一台满频一台降频，代码没变结论已翻。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>控制平台</strong>。测性能前先钉住环境：锁频或至少记录频率（<a href="/cs/cpufreq-governor">cpufreq governor</a> 的调度行为直接决定「同一份代码」跑在哪个 P-state 上）；独占机器，驱逐后台任务；固定数据、固定随机种子、固定 NUMA 绑定。时钟抖动与温度节流不改代码，只改数字——两次测量之间空调启停，就能制造一次「显著优化」。</p><p><strong>控制状态</strong>。预热到稳态再计时，或把冷启动单独当课题研究。缓存、分支预测器、JIT、页分配器全是有状态的机器，冷态测出来的是初始化成本。反向也要防「测的是热身副产品」：计时区间必须落在工作真正发生的窗口里。</p><p><strong>控制负载</strong>。负载形状从上一课的负载模型来：大小分布、读写比、到达过程照抄，尤其是突发。开环压测（按时间表发请求，不等响应）与闭环压测（等响应再发下一个）回答不同的问题：测系统容量用开环，测单请求路径用闭环，报告时写明用哪种。</p><p><strong>控制统计</strong>。多样本、多样本、多样本。报中位数与区间而不是最好的一次；事先定样本量，不要看到满意就停——那不是挑选就是噪声。</p><p><span class="marginnote">「开环/闭环」翻译成大白话：闭环像一个人排队——办完一个才取下一个号，系统越慢你的发起速率越慢；开环像一车人同时涌进来取号，系统再慢请求照样按时间表到达。前者量「一个请求的体验」，后者量「系统被打满时的容量与排队行为」，混用会答非所问。</span></p>',11)),(B(),t(n,null,{default:A(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOADM%5B%22%E8%B4%9F%E8%BD%BD%E6%A8%A1%E5%9E%8B%EF%BC%9A%E4%B8%8A%E4%B8%80%E8%AF%BE%E7%9A%84%E5%90%88%E5%90%8C%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E8%B4%9F%E8%BD%BD%EF%BC%9A%E5%BD%A2%E7%8A%B6%E7%85%A7%E6%8A%84%22%5D%0A%20%20GEN%20--%3E%20PLAT%5B%22%E6%8E%A7%E5%88%B6%E5%B9%B3%E5%8F%B0%EF%BC%9A%E9%94%81%E9%A2%91%E3%80%81%E7%8B%AC%E5%8D%A0%E3%80%81%E7%BB%91%E6%A0%B8%22%5D%0A%20%20PLAT%20--%3E%20STATE%5B%22%E6%8E%A7%E5%88%B6%E7%8A%B6%E6%80%81%EF%BC%9A%E9%A2%84%E7%83%AD%E5%88%B0%E7%A8%B3%E6%80%81%22%5D%0A%20%20STATE%20--%3E%20STAT%5B%22%E5%A4%9A%E6%A0%B7%E6%9C%AC%E7%BB%9F%E8%AE%A1%EF%BC%9A%E4%B8%AD%E4%BD%8D%E6%95%B0%E5%8A%A0%E5%8C%BA%E9%97%B4%22%5D%0A%20%20STAT%20--%3E%20JUDGE%7B%22%E5%AF%B9%E7%85%A7%E9%AA%8C%E6%94%B6%E5%8D%8F%E8%AE%AE%22%7D%0A%20%20JUDGE%20--%3E%7C%22%E5%8F%AF%E7%96%91%EF%BC%9A%E5%9B%9E%E5%88%B0%E6%8E%A7%E5%88%B6%E7%8E%AF%E8%8A%82%22%7C%20PLAT%0A%20%20JUDGE%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20REPORT%5B%22%E6%8A%A5%E5%91%8A%EF%BC%9A%E5%86%99%E6%98%8E%E7%8E%AF%E5%A2%83%E4%B8%8E%E5%8D%8F%E8%AE%AE%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("这些手段为什么缺一不可：性能不是代码的属性，是「代码加平台加状态」三元组的属性。锁频为什么必要——频率是乘在整条时间线上的因子，两组不同频率的对比不是测量是比较。预热为什么必要——稳态才是服务生涯的常态，用户几乎从不访问刚开机十分钟的机器。多样本为什么必要——单次计时的方差来自中断、缓存扰动与调度噪声，这些噪声不改均值却毁单次读数。标准化基准的 run rules（公开环境、禁止挑数字、禁止未披露选项）把这三条纪律写成了合同；"),a("a",{href:"/cs/spec-benchmark-pitfalls"},"SPEC 与基准陷阱"),e("的教训是受控比较不等于工作负载的充分统计——你的内部基准同样如此，它给出的是可控条件下的证据，不是生产预测。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"一个不花一分钱就能捏造 40% 「优化」的办法：把基准从下午四点挪到凌晨两点，机房降温和负载退潮让 turbo 频率多撑几百兆赫。频率记录缺席的基准报告，等于没写测量仪器型号。")],-1)),(B(),t(n,null,{default:A(()=>[l(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20CLOSED%5B%22%E9%97%AD%E7%8E%AF%E5%8E%8B%E6%B5%8B%22%5D%0A%20%20%20%20C1%5B%22%E5%8F%91%E8%AF%B7%E6%B1%82%201%22%5D%20--%3E%20C2%5B%22%E7%AD%89%E5%93%8D%E5%BA%94%E5%9B%9E%E6%9D%A5%22%5D%0A%20%20%20%20C2%20--%3E%20C3%5B%22%E6%89%8D%E5%8F%91%E8%AF%B7%E6%B1%82%202%22%5D%0A%20%20%20%20C3%20--%3E%20C4%5B%22%E5%90%9E%E5%90%90%E5%8F%97%E9%99%90%E4%BA%8E%E5%8D%95%E8%AF%B7%E6%B1%82%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20end%0A%20%20subgraph%20OPEN%5B%22%E5%BC%80%E7%8E%AF%E5%8E%8B%E6%B5%8B%22%5D%0A%20%20%20%20O1%5B%22%E5%AE%9A%E6%97%B6%E5%99%A8%E6%8C%89%E6%97%B6%E9%97%B4%E8%A1%A8%E5%8F%91%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20O2%5B%22%E4%B8%8D%E7%AD%89%E5%93%8D%E5%BA%94%EF%BC%8C%E7%BB%A7%E7%BB%AD%E5%8F%91%22%5D%0A%20%20%20%20O2%20--%3E%20O3%5B%22%E7%B3%BB%E7%BB%9F%E8%BF%87%E8%BD%BD%E6%97%B6%E9%98%9F%E5%88%97%E5%A0%86%E7%A7%AF%22%5D%0A%20%20%20%20O3%20--%3E%20O4%5B%22%E6%9A%B4%E9%9C%B2%E5%AE%B9%E9%87%8F%E4%B8%8E%E6%8E%92%E9%98%9F%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20end%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=s('<p>这张图回答的问题是：同样发请求，开环与闭环差在哪？闭环的下一个请求依赖上一个响应，系统变慢它自动减速，永远压不到过载；开环按既定节奏开火，系统跟不上时积压直接现形。想测「系统能扛多少」却用闭环压测，得到的上限其实是「单请求延迟的倒数」，不是容量。</p><p><span class="marginnote">数字实例：某接口平均延迟 10 ms，闭环单线程压测的「吞吐」约 100 请求/秒。换成开环 1000 请求/秒后 P99 可能飙到 800 ms——不是系统变慢了，是闭环数字从头就没量过容量这件事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>基准再规矩也不是生产。它测不到真实数据的分布、真实的邻居与真实的故障，所以内部基准永远要和现场遥测互相校准，两套数字打架时先怀疑负载模型。也警惕 Goodhart 定律：基准数字一旦变成考核，代码就会朝基准特化——为合成负载调的哈希表参数，在真实键分布上可能是负优化。标准化套件内部的实现细节（TPC 合同条款、SPEC 编译规则）主干课已交代，本课给的是自己动手时够用的护栏。</p><p><span class="marginnote">直觉类比：Goodhart 定律就像「用体检单上的某一项当 KPI」——大家不去锻炼身体，而是去研究怎么让这一项数字变好看。基准一旦和绩效挂钩，代码就会朝「让基准数字好看」特化，而不是朝「让用户快」优化，两者从此分道扬镳。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>基准测的是「代码加平台加状态」三元组；平台、状态、负载、统计，四环控制缺一失守。</li><li>锁频并记录频率，独占机器，固定数据与种子；漂移的频率是最便宜的造假与最常见的误判。</li><li>预热到稳态再计时，冷启动要么单测、要么不测。</li><li>多样本报中位数与区间，样本量事先定；「看到满意就停」是挑选不是测量。</li><li>基准是受控比较不是生产预测，与现场遥测互相校准；防基准特化。</li><li>出处：Jain，<em>The Art of Computer Systems Performance Analysis</em>，1991；SPEC 与 TPC 的 run rules；据本课四控制口径整理。</li></ul>',7))])}const T=o(d,[["render",D]]);export{u as __pageData,T as default};
